components.css:
.ds-push{display:inline-flex;align-items:center;gap:.6rem;min-height:3.25rem;padding:.8rem 1.4rem;border:2px solid var(--ink,#121512);border-radius:999px;background:var(--push,#f4c62f);color:var(--ink,#121512);font:800 .9375rem/1 Archivo,sans-serif;font-stretch:112%;text-transform:uppercase;letter-spacing:.04em;text-decoration:none;box-shadow:0 4px 0 var(--push-rim,#9a7608),0 6px 12px rgb(0 0 0/.22);transition:transform 120ms cubic-bezier(.16,1,.3,1),box-shadow 120ms cubic-bezier(.16,1,.3,1)}
.ds-push:hover{transform:translateY(-1px);box-shadow:0 5px 0 var(--push-rim,#9a7608),0 8px 14px rgb(0 0 0/.22)}
.ds-push:active{transform:translateY(4px);box-shadow:0 0 0 var(--push-rim,#9a7608),0 2px 4px rgb(0 0 0/.25)}
.ds-push:focus-visible{outline:3px solid var(--ink,#121512);outline-offset:3px}
.ds-push svg{width:1em;height:1em;flex:none;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

.ds-btn-plate{display:inline-flex;align-items:center;gap:.55rem;min-height:2.75rem;padding:.6rem 1rem;border:0;border-radius:3px;background:var(--plate,#161916);color:var(--plate-text,#eef1e8);font:400 .8125rem/1 "B612 Mono",monospace;letter-spacing:.02em;text-decoration:none;box-shadow:inset 0 1px 0 rgb(255 255 255/.08),0 3px 0 #000,0 4px 8px rgb(0 0 0/.2);transition:transform 120ms cubic-bezier(.16,1,.3,1),box-shadow 120ms cubic-bezier(.16,1,.3,1),background-color 120ms}
.ds-btn-plate:hover{background:var(--plate-2,#232823)}
.ds-btn-plate:active{transform:translateY(3px);box-shadow:inset 0 1px 0 rgb(255 255 255/.08),0 0 0 #000}
.ds-btn-plate:focus-visible{outline:3px solid var(--ink,#121512);outline-offset:3px}
.ds-btn-plate svg{width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

.ds-panel{position:relative;padding:1.25rem;border:2px solid var(--ink,#121512);border-radius:6px;background:var(--enamel-hi,#d8dfd2);box-shadow:0 2px 0 rgb(255 255 255/.5) inset,0 10px 28px rgb(20 30 18/.18)}
.ds-panel-head{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.75rem 1.25rem;margin-bottom:1rem}
.ds-panel-label{display:inline-block;margin:0;padding:.5rem .85rem .45rem;border-radius:3px;background:var(--plate,#161916);color:var(--plate-text,#eef1e8);font:800 1.35rem/1.1 Archivo,sans-serif;font-stretch:125%;text-transform:uppercase;letter-spacing:.05em;box-shadow:inset 0 1px 0 rgb(255 255 255/.08),0 1px 2px rgb(0 0 0/.25)}
.ds-panel-note{margin:0;font:400 .75rem/1.4 "B612 Mono",monospace;color:var(--ink-2,#384236)}
.ds-legend{display:flex;flex-wrap:wrap;align-items:center;gap:.4rem 1rem;font:400 .75rem/1 "B612 Mono",monospace;color:var(--ink-2,#384236)}
.ds-legend span{display:inline-flex;align-items:center;gap:.4rem}
.ds-legend i{display:inline-block;width:1.4rem;height:4px;background:var(--lamp,#fbfbf2);outline:3px solid var(--plate,#161916)}
.ds-legend i.r{background:var(--occupied,#e2392f);width:.9rem}

.ds-routeline{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem .9rem;padding:.45rem .5rem .45rem .3rem;border-radius:4px}
.ds-routeline:nth-child(odd){background:rgb(255 255 255/.22)}
.ds-routeline .ds-no{display:inline-grid;place-items:center;width:2.5rem;height:2.5rem;flex:none;border-radius:50%;background:var(--plate,#161916);color:var(--plate-text,#eef1e8);font:700 .875rem/1 "B612 Mono",monospace;box-shadow:inset 0 -3px 0 rgb(0 0 0/.5),0 0 0 3px var(--enamel-hi,#d8dfd2),0 0 0 5px rgb(18 21 18/.25);transition:box-shadow 200ms cubic-bezier(.16,1,.3,1),color 200ms}
.ds-term{margin:0;flex:1 1 8rem;font:400 .75rem/1.3 "B612 Mono",monospace;color:var(--ink-2,#384236)}
.ds-term b{display:block;font-size:.625rem;font-weight:700;letter-spacing:.12em;color:var(--ink,#121512)}
.ds-term--out{text-align:right}
.ds-track{container-type:inline-size;position:relative;display:flex;align-items:center;justify-content:space-around;gap:.4rem;flex:2 1 12rem;min-height:2.25rem;overflow:hidden}
.ds-track::before{content:"";position:absolute;left:0;right:0;top:50%;height:8px;margin-top:-4px;background:var(--plate,#161916);border-radius:1px}
.ds-track-lamp{position:absolute;left:0;right:0;top:50%;height:2px;margin-top:-1px;background:var(--lamp,#fbfbf2);transform:scaleX(0);transform-origin:left;transition:transform 160ms steps(2,end)}
.ds-routeline .ds-st{position:relative;flex:none;padding:.45rem .55rem;border:1px solid var(--plate,#161916);border-radius:3px;background:var(--plate,#161916);color:var(--plate-text,#eef1e8);font:400 .6875rem/1 "B612 Mono",monospace;white-space:nowrap;transition:border-color 200ms cubic-bezier(.16,1,.3,1)}
.ds-occ{position:absolute;left:0;top:50%;width:2.75rem;height:4px;margin-top:-2px;border-radius:2px;background:var(--occupied,#e2392f);transform:translateX(-3rem)}
.ds-routeline:hover .ds-track-lamp{transform:scaleX(1);transition:transform 640ms steps(8,end)}
.ds-routeline:hover .ds-st{border-color:var(--lamp,#fbfbf2);transition-delay:120ms}
.ds-routeline:hover .ds-st+.ds-st{transition-delay:270ms}
.ds-routeline:hover .ds-no{color:var(--lamp,#fbfbf2);box-shadow:inset 0 -3px 0 rgb(0 0 0/.5),0 0 0 3px var(--lamp,#fbfbf2),0 0 0 5px var(--plate,#161916)}
.ds-routeline:hover .ds-occ{animation:ds-occ 1.7s cubic-bezier(.45,0,.35,1) .55s both}
@keyframes ds-occ{from{transform:translateX(-3rem)}to{transform:translateX(100cqw)}}
.ds-routeline:focus-within .ds-track-lamp{transform:scaleX(1)}
@media (prefers-reduced-motion: reduce){.ds-track-lamp,.ds-st,.ds-no{transition:none}.ds-routeline:hover .ds-occ{animation:none}}
